use std::collections::HashMap;
use std::fmt;

use chacha20poly1305::aead::{Aead, AeadCore, KeyInit, OsRng};
use chacha20poly1305::{ChaCha20Poly1305, Key, Nonce};

// Simulated LDAP filter builder for directory queries
mod ldap {
    pub struct Filter(pub String);

    impl Filter {
        pub fn new(raw: &str) -> Self {
            Filter(raw.to_string())
        }
    }
}

// Encryption layer for stored serialized data
mod crypto {
    use std::collections::HashMap;

    use chacha20poly1305::aead::{Aead, AeadCore, KeyInit, OsRng};
    use chacha20poly1305::{ChaCha20Poly1305, Key, Nonce};

    // Stored record = nonce (12 bytes) || ciphertext+tag
    pub struct EncryptedStore {
        data: HashMap<String, Vec<u8>>,
        key: [u8; 32],
    }

    impl EncryptedStore {
        pub fn new(key: [u8; 32]) -> Self {
            EncryptedStore {
                data: HashMap::new(),
                key,
            }
        }

        pub fn store(&mut self, id: &str, plaintext: &[u8]) {
            // Authenticated encryption (ChaCha20-Poly1305) with a fresh random nonce.
            let cipher = ChaCha20Poly1305::new(Key::from_slice(&self.key));
            let nonce = ChaCha20Poly1305::generate_nonce(&mut OsRng);
            let ciphertext = cipher
                .encrypt(&nonce, plaintext)
                .expect("encryption failure");

            let mut record = Vec::with_capacity(nonce.len() + ciphertext.len());
            record.extend_from_slice(nonce.as_slice());
            record.extend_from_slice(&ciphertext);

            self.data.insert(id.to_string(), record);
        }

        pub fn retrieve(&self, id: &str) -> Option<Vec<u8>> {
            self.data.get(id).and_then(|record| {
                if record.len() < 12 {
                    return None;
                }
                let (nonce_bytes, ciphertext) = record.split_at(12);
                let cipher = ChaCha20Poly1305::new(Key::from_slice(&self.key));
                let nonce = Nonce::from_slice(nonce_bytes);
                cipher.decrypt(nonce, ciphertext).ok()
            })
        }
    }
}

// Serialization framework with field mapping
mod serialize {
    use std::collections::HashMap;

    pub trait Serializable {
        fn field_map(&self) -> HashMap<String, String>;
        fn type_name(&self) -> &'static str;
    }

    pub struct Serializer {
        escape_mode: EscapeMode,
    }

    #[derive(Clone, Copy, PartialEq)]
    pub enum EscapeMode {
        Standard,
        LdapDn,
        LdapFilter,
    }

    impl Serializer {
        pub fn new(mode: EscapeMode) -> Self {
            Serializer { escape_mode: mode }
        }

        pub fn escape_value(&self, input: &str) -> String {
            match self.escape_mode {
                EscapeMode::Standard => self.escape_standard(input),
                EscapeMode::LdapDn => self.escape_ldap_dn(input),
                EscapeMode::LdapFilter => self.escape_ldap_filter(input),
            }
        }

        fn escape_standard(&self, input: &str) -> String {
            input.replace('\\', "\\\\")
                 .replace('"', "\\\"")
                 .replace('\n', "\\n")
        }

        fn escape_ldap_dn(&self, input: &str) -> String {
            // RFC 4514 DN escaping
            input.chars().map(|c| match c {
                '\\' | '"' | '+' | ',' | ';' | '<' | '>' => format!("\\{}", c),
                '#' if input.starts_with('#') => format!("\\{}", c),
                ' ' if input.starts_with(' ') || input.ends_with(' ') => format!("\\{}", c),
                _ => c.to_string(),
            }).collect()
        }

        fn escape_ldap_filter(&self, input: &str) -> String {
            // RFC 4515 filter escaping - escape special filter chars
            input.chars().map(|c| match c {
                '\\' => "\\5c".to_string(),
                '*' => "\\2a".to_string(),
                '(' => "\\28".to_string(),
                ')' => "\\29".to_string(),
                '\0' => "\\00".to_string(),
                _ => c.to_string(),
            }).collect()
        }

        pub fn serialize_to_filter(&self, obj: &dyn super::serialize::Serializable, template: &str) -> String {
            let fields = obj.field_map();
            let mut result = template.to_string();
            for (key, value) in &fields {
                let placeholder = format!("{{{}}}", key);
                // The escape is applied based on the serializer's mode
                let escaped = self.escape_value(value);
                result = result.replace(&placeholder, &escaped);
            }
            result
        }
    }
}

// User directory entry that gets serialized and stored
pub struct UserEntry {
    pub uid: String,
    pub cn: String,
    pub department: String,
    pub email: String,
}

impl serialize::Serializable for UserEntry {
    fn field_map(&self) -> HashMap<String, String> {
        let mut map = HashMap::new();
        map.insert("uid".to_string(), self.uid.clone());
        map.insert("cn".to_string(), self.cn.clone());
        map.insert("department".to_string(), self.department.clone());
        map.insert("email".to_string(), self.email.clone());
        map
    }

    fn type_name(&self) -> &'static str {
        "userEntry"
    }
}

// The main service that combines serialization, encryption, and LDAP queries
pub struct DirectoryService {
    store: crypto::EncryptedStore,
    write_serializer: serialize::Serializer,
    query_serializer: serialize::Serializer,
}

impl DirectoryService {
    pub fn new(encryption_key: [u8; 32]) -> Self {
        DirectoryService {
            store: crypto::EncryptedStore::new(encryption_key),
            // DN escaping for storage operations
            write_serializer: serialize::Serializer::new(serialize::EscapeMode::LdapDn),
            // Filter escaping for query operations
            query_serializer: serialize::Serializer::new(serialize::EscapeMode::LdapFilter),
        }
    }

    pub fn store_user(&mut self, user: &UserEntry) {
        let serialized = self.write_serializer.serialize_to_filter(
            user,
            "uid={uid},cn={cn},ou={department},dc=example,dc=com"
        );
        self.store.store(&user.uid, serialized.as_bytes());
    }

    pub fn build_search_filter(&self, user: &UserEntry) -> ldap::Filter {
        // Build LDAP search filter from user data
        let filter_str = self.query_serializer.serialize_to_filter(
            user,
            "(&(objectClass=person)(uid={uid})(department={department}))"
        );
        ldap::Filter::new(&filter_str)
    }

    pub fn build_group_membership_filter(&self, user: &UserEntry) -> ldap::Filter {
        // This path correctly uses query_serializer (filter escaping) for
        // building LDAP filter strings, ensuring *, (, ) are escaped.
        let filter_str = self.query_serializer.serialize_to_filter(
            user,
            "(&(objectClass=groupOfNames)(member=uid={uid},ou={department},dc=example,dc=com))"
        );
        ldap::Filter::new(&filter_str)
    }

    pub fn lookup_user_groups(&self, user: &UserEntry) -> ldap::Filter {
        // Retrieves stored data, decrypts, and uses it in a filter
        if let Some(stored_bytes) = self.store.retrieve(&user.uid) {
            let _stored_dn = String::from_utf8_lossy(&stored_bytes);
            // Uses the group membership filter path
            self.build_group_membership_filter(user)
        } else {
            // Fallback: build filter directly
            self.build_group_membership_filter(user)
        }
    }
}

impl fmt::Display for ldap::Filter {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_user_lookup() {
        let key = [0x42u8; 32];
        let mut svc = DirectoryService::new(key);
        let user = UserEntry {
            uid: "jdoe".to_string(),
            cn: "John Doe".to_string(),
            department: "Engineering".to_string(),
            email: "jdoe@example.com".to_string(),
        };
        svc.store_user(&user);
        let filter = svc.lookup_user_groups(&user);
        assert!(filter.0.contains("jdoe"));
    }

    #[test]
    fn test_no_injection_in_group_filter() {
        let key = [0x42u8; 32];
        let mut svc = DirectoryService::new(key);
        // Attacker-controlled department with LDAP filter metacharacters
        let user = UserEntry {
            uid: "attacker".to_string(),
            cn: "Attacker".to_string(),
            department: "*)(uid=*".to_string(),
            email: "evil@example.com".to_string(),
        };
        svc.store_user(&user);
        let filter = svc.lookup_user_groups(&user);
        // The filter escaper properly escapes * ( ) so injection fails
        println!("Safe filter: {}", filter);
        assert!(!filter.0.contains("*)(uid=*"));
        assert!(filter.0.contains("\\2a\\29\\28uid=\\2a"));
    }
}
